import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    existing = set(columns)
    number = 1
    while len(columns) < width:
        name = f"Extra column {number}"
        number += 1
        if name not in existing:
            columns.append(name)
            existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
